const cfg = $('Config').first().json;
const commitsRaw = $('GitHub Commits').all().map(i => i.json).flat();
const issuesRaw = $('GitHub Closed Issues').all().map(i => i.json).flat();
const prsRaw = $('GitHub Closed PRs').all().map(i => i.json).flat();

function asArr(x) {
  if (Array.isArray(x)) return x;
  if (x && Array.isArray(x.items)) return x.items;
  return x ? [x] : [];
}

const commits = asArr(commitsRaw).slice(0, 80).map(c => ({
  sha: (c.sha || '').slice(0, 7),
  message: (c.commit && c.commit.message || '').split('\n')[0],
  author: c.commit && c.commit.author && c.commit.author.name
}));

const since = new Date(cfg.sinceIso).getTime();
const closedIssues = asArr(issuesRaw).filter(i => !i.pull_request).slice(0, 60).map(i => ({
  number: i.number, title: i.title, closed_at: i.closed_at
}));

const mergedPrs = asArr(prsRaw).filter(p => p.merged_at && new Date(p.merged_at).getTime() >= since).slice(0, 60).map(p => ({
  number: p.number, title: p.title, merged_at: p.merged_at, user: p.user && p.user.login
}));

const lang = (cfg.language || 'EN').toUpperCase();
const langLine = lang === 'FR'
  ? 'Rédige le résumé en français.'
  : 'Write the summary in English.';

const prompt = [
  `You are a helpful engineering manager writing a weekly narrative summary for GitHub repo ${cfg.githubRepo}.`,
  langLine,
  'Cover themes, notable merges, closed issues, and risks. Keep it under 400 words.',
  '',
  'COMMITS:',
  JSON.stringify(commits, null, 2),
  '',
  'CLOSED_ISSUES (no PRs):',
  JSON.stringify(closedIssues, null, 2),
  '',
  'MERGED_PRS (last 7 days):',
  JSON.stringify(mergedPrs, null, 2)
].join('\n');

return [{
  json: {
    githubRepo: cfg.githubRepo,
    language: lang,
    discordWebhook: cfg.discordWebhook,
    counts: { commits: commits.length, issues: closedIssues.length, mergedPrs: mergedPrs.length },
    prompt
  }
}];

const agg = $('Aggregate Activity').first().json;
const claude = $input.first().json;
let text = '';
if (claude && Array.isArray(claude.content)) {
  text = claude.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
} else {
  text = JSON.stringify(claude).slice(0, 1500);
}
const header = `**Weekly summary — ${agg.githubRepo}** (${agg.language})\ncommits=${agg.counts.commits} issues=${agg.counts.issues} mergedPRs=${agg.counts.mergedPrs}\n\n`;
return [{ json: { content: header + text, discordWebhook: agg.discordWebhook } }];
